SELECT c.symbol, c.closed, c.ingestion_source, (c.close_transition_token IS NOT NULL) AS has_token, c.updated_at, (SELECT GROUP_CONCAT(CONCAT(o.outcome,'/',o.origin)) FROM candle_analysis_outcome o WHERE o.symbol = c.symbol AND o.interval_code = c.interval_code AND o.candle_open_time = c.open_time) AS outcomes, (SELECT COUNT(*) FROM trade_signal s WHERE s.symbol = c.symbol AND s.interval_code = '1h' AND s.candle_open_time = c.open_time) AS signals FROM candle c WHERE c.interval_code = '1h' AND c.open_time = '2026-10-10 17:00:00' ORDER BY c.updated_at